<section class="bg-white rounded-3xl border p-4"><div class="flex justify-between mb-3"><h3 class="text-xs font-black">Importaciones recientes</h3><button @click="loadBatches()" class="material-icons text-base text-slate-400">refresh</button></div><div class="space-y-2 max-h-64 overflow-y-auto scrollbar"><template x-for="b in batches" :key="b.id"><button @click="openBatch(b.id)" :class="Number(activeBatch)===Number(b.id)?'border-emerald-400 bg-emerald-50':'border-slate-100 bg-slate-50'" class="w-full border rounded-xl p-3 text-left"><div class="flex gap-2"><span class="material-icons text-base" :class="b.import_type==='payment_capture'?'text-emerald-600':'text-blue-600'" x-text="b.import_type==='payment_capture'?'payments':'account_balance'"></span><span class="text-[10px] font-black truncate" x-text="b.source_name"></span><span class="ml-auto text-[9px] font-black" x-text="b.status==='completed'?'Lista':'Pendiente'"></span></div><p class="text-[9px] text-slate-400 mt-1"><span x-text="dateLabel(b.created_at)"></span> · <span x-text="b.applied_count||0"></span>/<span x-text="b.item_count"></span></p></button></template><p x-show="!batches.length" class="text-[11px] text-slate-400 text-center py-4">Aún no hay importaciones.</p></div></section>
