<section class="min-w-0 space-y-4">
<div class="grid grid-cols-3 gap-2"><template x-for="s in [{l:'Por revisar',v:summary.pending,c:'slate'},{l:'Duplicados',v:summary.duplicates,c:'amber'},{l:'Aplicados',v:summary.applied,c:'emerald'}]"><div class="bg-white border rounded-2xl p-3"><p class="text-[9px] font-black uppercase text-slate-400" x-text="s.l"></p><p class="text-xl font-black mt-1" :class="s.c==='amber'?'text-amber-700':s.c==='emerald'?'text-emerald-700':''" x-text="s.v"></p></div></template></div>
<div class="bg-white border rounded-3xl overflow-hidden"><div class="p-4 border-b flex flex-col sm:flex-row gap-3 sm:items-center"><div><h2 class="font-black text-sm">Bandeja de revisión</h2><p class="text-[10px] text-slate-400">Verifica cada sugerencia antes de registrarla.</p></div><div class="sm:ml-auto flex gap-2"><input x-model="search" placeholder="Buscar..." class="h-10 min-w-0 w-full sm:w-44 px-3 bg-slate-50 border rounded-xl text-xs"><select x-model="filter" class="h-10 bg-slate-50 border rounded-xl px-2 text-[10px] font-black"><option value="all">Todos</option><option value="pending">Pendientes</option><option value="duplicate">Duplicados</option><option value="applied">Aplicados</option><option value="ignored">Ignorados</option></select></div></div>
<div class="divide-y"><template x-for="item in filteredItems" :key="item.id"><article class="p-3 sm:p-4"><div class="flex gap-3"><div class="w-11 h-11 shrink-0 rounded-2xl flex items-center justify-center" :class="item.direction==='credit'?'bg-emerald-100 text-emerald-700':'bg-rose-100 text-rose-700'"><span class="material-icons" x-text="item.direction==='credit'?'south_west':'north_east'"></span></div><div class="min-w-0 flex-1"><div class="flex flex-wrap gap-1"><p class="font-black text-sm truncate" x-text="item.counterparty||item.description||'Movimiento bancario'"></p><span class="text-[9px] font-black rounded-md px-1.5 py-1" :class="statusClass(item.status)" x-text="statusLabel(item.status)"></span><span x-show="item.suggested_action==='transfer'" class="text-[9px] font-black rounded-md px-1.5 py-1 bg-blue-100 text-blue-700">Posible traslado</span></div><div class="mt-1 text-[10px] text-slate-500 font-semibold"><span x-text="dateLabel(item.movement_date)"></span><span x-show="item.reference"> · Ref. <b x-text="item.reference"></b></span><span x-show="item.bank"> · <span x-text="item.bank"></span></span></div><div x-show="item.matched_order_id" class="mt-2 rounded-xl bg-emerald-50 border border-emerald-100 p-2 text-[10px] font-black"><span class="text-emerald-600">Deuda sugerida:</span> Orden #<span x-text="item.matched_order_id"></span> · <span x-text="item.customer_name"></span></div></div><div class="text-right shrink-0"><p class="font-black text-sm" :class="item.direction==='credit'?'text-emerald-700':'text-rose-600'" x-text="(item.direction==='credit'?'+':'−')+money(item.amount,item.currency)"></p><p class="text-[9px] text-slate-400 font-bold" x-text="item.account_name"></p></div></div><div x-show="item.status==='pending'||item.status==='duplicate'" class="mt-3 flex gap-2 justify-end"><button @click="openReview(item)" class="h-9 px-3 rounded-xl border text-[10px] font-black">Revisar</button><button @click="ignore(item)" class="h-9 px-3 rounded-xl bg-slate-100 text-[10px] font-black">Ignorar</button><button @click="quickApply(item)" class="h-9 px-3 rounded-xl bg-slate-900 text-white text-[10px] font-black" x-text="actionLabel(item.suggested_action)"></button></div></article></template><div x-show="!filteredItems.length" class="py-20 text-center"><span class="material-icons text-5xl text-slate-200">inbox</span><p class="text-sm font-black text-slate-500">No hay movimientos en esta vista</p></div></div>
</div></section></main>
<div x-cloak x-show="review.open" class="fixed inset-0 z-50 flex items-end sm:items-center justify-center sm:p-4"><div class="absolute inset-0 bg-slate-950/60" @click="review.open=false"></div><div class="relative w-full sm:max-w-lg bg-white rounded-t-3xl sm:rounded-3xl max-h-[92vh] overflow-y-auto"><div class="sticky top-0 bg-white px-5 py-4 border-b flex z-10"><div><h3 class="font-black">Revisar movimiento</h3><p class="text-[10px] text-slate-400">Corrige datos y elige la acción.</p></div><button @click="review.open=false" class="ml-auto w-9 h-9 rounded-xl bg-slate-100"><span class="material-icons text-base">close</span></button></div><div class="p-5 space-y-4" x-show="review.item">
<div class="grid grid-cols-2 gap-3"><label class="text-[10px] font-black">Monto<input type="number" step=".01" x-model.number="review.item.amount" class="mt-1 w-full h-11 rounded-xl border px-3 font-black"></label><label class="text-[10px] font-black">Moneda<select x-model="review.item.currency" class="mt-1 w-full h-11 rounded-xl border px-3 font-black"><option>BS</option><option>USD</option><option>EUR</option></select></label></div><div class="grid grid-cols-2 gap-3"><label class="text-[10px] font-black">Tipo<select x-model="review.item.direction" class="mt-1 w-full h-11 rounded-xl border px-3 text-xs font-black"><option value="credit">Entrada</option><option value="debit">Salida</option></select></label><label class="text-[10px] font-black">Fecha<input type="datetime-local" x-model="review.item.movement_date_local" class="mt-1 w-full h-11 rounded-xl border px-2 text-[11px]"></label></div><label class="block text-[10px] font-black">Referencia<input x-model="review.item.reference" class="mt-1 w-full h-11 rounded-xl border px-3 text-xs"></label><label class="block text-[10px] font-black">Contraparte<input x-model="review.item.counterparty" class="mt-1 w-full h-11 rounded-xl border px-3 text-xs"></label><label class="block text-[10px] font-black">Descripción<textarea x-model="review.item.description" rows="2" class="mt-1 w-full rounded-xl border p-3 text-xs"></textarea></label>
<div><p class="text-[10px] font-black mb-2">¿Qué deseas hacer?</p><div class="grid grid-cols-3 gap-2"><template x-for="a in [{v:'payment',i:'payments',l:'Abono'},{v:'transaction',i:'receipt_long',l:'Movimiento'},{v:'transfer',i:'sync_alt',l:'Traslado'}]"><button @click="review.action=a.v" :class="review.action===a.v?'bg-emerald-600 text-white':'bg-slate-100 text-slate-600'" class="py-3 rounded-xl text-[10px] font-black"><span class="material-icons text-lg block" x-text="a.i"></span><span x-text="a.l"></span></button></template></div></div>
<label x-show="review.action==='payment'" class="block text-[10px] font-black">Deuda de impresiones<select x-model="review.orderId" class="mt-1 w-full h-12 rounded-xl border border-emerald-200 bg-emerald-50 px-3 text-xs font-black"><option value="">Seleccionar deuda</option><template x-for="d in debts" :key="d.id"><option :value="d.id" x-text="'#'+d.id+' · '+d.customer_name+' · '+money(d.remaining_bs,'BS')"></option></template></select></label><label x-show="review.action==='transfer'" class="block text-[10px] font-black">Otra cuenta del traslado<select x-model="review.destinationId" class="mt-1 w-full h-12 rounded-xl border border-blue-200 bg-blue-50 px-3 text-xs font-black"><option value="">Seleccionar la otra cuenta</option><template x-for="a in accounts.filter(a=>Number(a.id)!==Number(review.item.account_id))" :key="a.id"><option :value="a.id" x-text="a.name+' · '+a.currency"></option></template></select><span class="block mt-1 text-[9px] text-slate-400" x-text="review.item.direction==='credit'?'Esta será la cuenta de origen.':'Esta será la cuenta destino.'"></span></label><div x-show="review.item.status==='duplicate'" class="p-3 rounded-xl bg-amber-50 border border-amber-200 text-[11px] text-amber-800 font-bold">Coincide con un movimiento importado. Confirma solo si verificaste que es distinto.</div><button @click="saveAndApply()" :disabled="review.loading" class="w-full h-12 rounded-2xl bg-emerald-600 text-white font-black text-xs" x-text="review.loading?'Guardando...':'Guardar y confirmar'"></button>
<label x-show="review.action==='payment'" class="block text-[10px] font-black">Deuda de impresiones<select x-model="review.orderId" class="mt-1 w-full h-12 rounded-xl border border-emerald-200 bg-emerald-50 px-3 text-xs font-black"><option value="">Seleccionar deuda</option><template x-for="d in debts" :key="d.id"><option :value="d.id" x-text="'#'+d.id+' · '+d.customer_name+' · '+money(d.remaining_bs,'BS')"></option></template></select></label><label x-show="review.action==='transaction'" class="block text-[10px] font-black">Categoría<select x-model="review.categoryId" class="mt-1 w-full h-12 rounded-xl border bg-slate-50 px-3 text-xs font-black"><option value="">Categoría automática</option><template x-for="c in categories.filter(c=>c.type===(review.item.direction==='credit'?'income':'expense'))" :key="c.id"><option :value="c.id" x-text="c.name"></option></template></select></label><label x-show="review.action==='transfer'" class="block text-[10px] font-black">Otra cuenta del traslado<select x-model="review.destinationId" class="mt-1 w-full h-12 rounded-xl border border-blue-200 bg-blue-50 px-3 text-xs font-black"><option value="">Seleccionar la otra cuenta</option><template x-for="a in accounts.filter(a=>Number(a.id)!==Number(review.item.account_id))" :key="a.id"><option :value="a.id" x-text="a.name+' · '+a.currency"></option></template></select><span class="block mt-1 text-[9px] text-slate-400" x-text="review.item.direction==='credit'?'Esta será la cuenta de origen.':'Esta será la cuenta destino.'"></span></label><div x-show="review.item.status==='duplicate'" class="p-3 rounded-xl bg-amber-50 border border-amber-200 text-[11px] text-amber-800 font-bold">Coincide con un movimiento importado. Confirma solo si verificaste que es distinto.</div><button @click="saveAndApply()" :disabled="review.loading" class="w-full h-12 rounded-2xl bg-emerald-600 text-white font-black text-xs" x-text="review.loading?'Guardando...':'Guardar y confirmar'"></button>
</div></div></div>
<div x-cloak x-show="settingsOpen" class="fixed inset-0 z-[60] flex items-center justify-center p-4"><div class="absolute inset-0 bg-slate-950/60" @click="settingsOpen=false"></div><div class="relative bg-white rounded-3xl p-5 w-full max-w-sm"><h3 class="font-black">Conexión Gemini</h3><p class="text-xs text-slate-500 mt-1">Se guarda solo en este dispositivo. CSV no necesita clave.</p><input type="password" x-model="tempKey" placeholder="AIza..." class="mt-4 w-full h-11 rounded-xl border px-3 text-xs"><div class="flex gap-2 mt-3"><button @click="settingsOpen=false" class="flex-1 h-10 rounded-xl bg-slate-100 text-xs font-black">Cancelar</button><button @click="saveKey()" class="flex-1 h-10 rounded-xl bg-emerald-600 text-white text-xs font-black">Guardar</button></div></div></div>
<div x-cloak x-show="toast" class="fixed bottom-5 left-1/2 -translate-x-1/2 z-[80] max-w-[90vw] px-4 py-3 rounded-2xl text-white text-xs font-black shadow-xl" :class="toastType==='error'?'bg-rose-600':'bg-slate-900'" x-text="toast"></div>
<script>
function reconciliationApp(){return{accounts:<?= json_encode($accounts,JSON_UNESCAPED_UNICODE) ?>,categories:<?= json_encode($categories,JSON_UNESCAPED_UNICODE) ?>,batches:<?= json_encode($batches,JSON_UNESCAPED_UNICODE) ?>,items:[],debts:[],activeBatch:null,importType:'payment_capture',accountId:'',files:[],loading:false,apiKey:localStorage.getItem('gemini_api_key')||'',tempKey:'',settingsOpen:false,search:'',filter:'all',toast:'',toastType:'success',review:{open:false,item:null,action:'transaction',orderId:'',destinationId:'',categoryId:'',loading:false},init(){this.tempKey=this.apiKey;if(this.batches.length)this.openBatch(this.batches[0].id);this.loadDebts()},get filteredItems(){let q=this.search.toLowerCase().trim();return this.items.filter(i=>(this.filter==='all'||i.status===this.filter)&&(!q||[i.reference,i.counterparty,i.description,i.bank,i.customer_name].join(' ').toLowerCase().includes(q)))},get summary(){return{pending:this.items.filter(i=>i.status==='pending').length,duplicates:this.items.filter(i=>i.status==='duplicate').length,applied:this.items.filter(i=>i.status==='applied').length}},async pickFiles(e){this.files=[];for(let f of [...e.target.files]){if(f.size>12*1024*1024){this.notify(f.name+' supera 12 MB','error');continue}this.files.push({name:f.name,mime:f.type||'application/octet-stream',data:await new Promise((ok,no)=>{let r=new FileReader;r.onload=()=>ok(r.result);r.onerror=no;r.readAsDataURL(f)})}); }e.target.value=''},async scan(){if(this.files.some(f=>!f.mime.includes('csv')&&!f.name.toLowerCase().endsWith('.csv'))&&!this.apiKey){this.settingsOpen=true;return this.notify('Agrega tu clave Gemini.','error')}this.loading=true;try{let d=await this.request('<?= base_url('reconciliation/scan') ?>',{import_type:this.importType,account_id:this.accountId,files:this.files,api_key:this.apiKey});this.activeBatch=d.batch_id;this.items=d.data||[];this.files=[];await this.loadBatches();this.notify('Documento analizado. Revisa las sugerencias.')}catch(e){this.notify(e.message,'error')}finally{this.loading=false}},async loadBatches(){try{this.batches=(await this.get('<?= base_url('reconciliation/batches') ?>')).data||[]}catch(e){}},async openBatch(id){this.activeBatch=id;try{this.items=(await this.get('<?= base_url('reconciliation/items') ?>?batch_id='+id)).data||[]}catch(e){this.notify(e.message,'error')}},async loadDebts(){try{this.debts=(await this.get('<?= base_url('reconciliation/debts') ?>')).data||[]}catch(e){}},openReview(i){let c=JSON.parse(JSON.stringify(i));c.movement_date_local=(c.movement_date||'').replace(' ','T').slice(0,16);this.review={open:true,item:c,action:c.suggested_action||'transaction',orderId:c.matched_order_id||'',destinationId:'',categoryId:'',loading:false}},async saveAndApply(){let r=this.review;if(r.action==='payment'&&!r.orderId)return this.notify('Selecciona una deuda.','error');if(r.action==='transfer'&&!r.destinationId)return this.notify('Selecciona el destino.','error');r.loading=true;try{await this.request('<?= base_url('reconciliation/item/') ?>'+r.item.id,{amount:r.item.amount,currency:r.item.currency,direction:r.item.direction,movement_date:r.item.movement_date_local,reference:r.item.reference,counterparty:r.item.counterparty,description:r.item.description,suggested_action:r.action,matched_order_id:r.orderId||null});await this.applyItem(r.item.id,r.action,r.orderId,r.destinationId,r.categoryId);r.open=false}catch(e){this.notify(e.message,'error')}finally{r.loading=false}},async quickApply(i){if(i.status==='duplicate'||i.suggested_action==='transfer'||(i.suggested_action==='payment'&&!i.matched_order_id))return this.openReview(i);await this.applyItem(i.id,i.suggested_action,i.matched_order_id,'','')},async ignore(i){await this.applyItem(i.id,'ignore','','','')},async applyItem(id,action,orderId,destinationId,categoryId){let d=await this.request('<?= base_url('reconciliation/apply/') ?>'+id,{action,order_id:orderId||null,destination_account_id:destinationId||null,category_id:categoryId||null});this.notify(d.message||'Confirmado.');await Promise.all([this.openBatch(this.activeBatch),this.loadBatches(),this.loadDebts()])},actionLabel(a){return a==='payment'?'Aplicar abono':a==='transfer'?'Revisar traslado':'Registrar'},statusLabel(s){return({pending:'Pendiente',duplicate:'Duplicado',applied:'Aplicado',ignored:'Ignorado'})[s]||s},statusClass(s){return({pending:'bg-blue-100 text-blue-700',duplicate:'bg-amber-100 text-amber-700',applied:'bg-emerald-100 text-emerald-700',ignored:'bg-slate-100 text-slate-500'})[s]},money(v,c){return(c==='USD'?'$ ':c==='EUR'?'€ ':'Bs. ')+Number(v||0).toLocaleString('es-VE',{minimumFractionDigits:2,maximumFractionDigits:2})},dateLabel(v){if(!v)return'—';let d=new Date(v.replace(' ','T'));return isNaN(d)?v:d.toLocaleString('es-VE',{dateStyle:'short',timeStyle:'short'})},saveKey(){this.apiKey=this.tempKey.trim();localStorage.setItem('gemini_api_key',this.apiKey);this.settingsOpen=false;this.notify('Clave guardada.')},notify(m,t='success'){this.toast=m;this.toastType=t;clearTimeout(this._tt);this._tt=setTimeout(()=>this.toast='',3500)},async get(u){let r=await fetch(u),d=await r.json();if(!r.ok||d.status==='error')throw Error(d.message||'No se pudo completar.');return d},async request(u,b){let r=await fetch(u,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(b)}),d=await r.json();if(!r.ok||d.status==='error')throw Error(d.message||'No se pudo completar.');return d}}}
</script></body></html>
